/**
 * Data for the interactive tools. The JSON files are generated by scripts/split-playbook.mjs
 * from the playbook source (checklist, Definition of Done, T12): do not edit them by hand.
 */
import en from './tools/en.json';
import it from './tools/it.json';
import type { Locale } from '~/lib/i18n';

export interface ToolItem {
  id: string;
  text: string;
}
export interface ChecklistSection {
  id: string;
  phase: string;
  title: string;
  items: ToolItem[];
}
export interface ToolsData {
  checklist: ChecklistSection[];
  dod: Record<string, { title: string; items: ToolItem[] }>;
  context: Record<'start' | 'during' | 'end', { title: string; items: ToolItem[] }>;
}

export const toolsData: Record<Locale, ToolsData> = { en, it } as Record<Locale, ToolsData>;

export const PHASES = ['F0', 'F1', 'F2', 'F3', 'F4', 'F5', 'F6', 'F7', 'F8'] as const;
export type PhaseId = (typeof PHASES)[number];

/** Page slug of each phase (same in both locales). */
export const PHASE_SLUGS: Record<PhaseId, string> = {
  F0: 'phases/f0-setup',
  F1: 'phases/f1-preliminary-spec',
  F2: 'phases/f2-discovery',
  F3: 'phases/f3-spec-architecture',
  F4: 'phases/f4-build-phases',
  F5: 'phases/f5-build-loop',
  F6: 'phases/f6-integration',
  F7: 'phases/f7-deploy',
  F8: 'phases/f8-post-launch',
};

export { pathFor } from '~/lib/paths';
